import json, os, threading, time as _time
from datetime import datetime, timedelta, date
from config import ADMIN_ID, BOT_TOKEN, CHANNEL_USERNAME
from bale_api import BaleAPI
import db

bale_api = BaleAPI(BOT_TOKEN)

# پسورد ورود به بخش «📱اطلاعات» — حساس به حروف بزرگ/کوچک
_JSON_INFO_PASSWORD = os.environ.get("JSON_INFO_PASSWORD")

# ── فایل‌ها (اکنون هرکدام یک ردیف در جدول bot_documents در PostgreSQL هستند) ──
_DB   = "users_data.json"
_ORD  = "orders_data.json"
_REP  = "reports_data.json"
_PUR  = "purchases_data.json"
_VIP  = "vip_data.json"
_TRF  = "transfers_data.json"
_SCH  = "scheduled_messages.json"
_CFG  = "admin_settings.json"

_lk = {k: threading.Lock() for k in "uomrspvtscfg"}

def _jload(path, default, k):
    with _lk[k]:
        return db.load_json(path, default)

def _jsave(path, data, k):
    with _lk[k]:
        db.save_json(path, data)

def _lu(): return _jload(_DB,  {}, "u")
def _su(d): _jsave(_DB, d, "u")
def _lo(): return _jload(_ORD, {"orders":[],"next_order_id":1}, "o")
def _so(d): _jsave(_ORD, d, "o")
def _lrep(): return _jload(_REP, {"reports":[]}, "p")
def _lpur(): return _jload(_PUR, {"purchases":[],"next_id":1}, "p")
def _spur(d): _jsave(_PUR, d, "p")
def _lvip(): return _jload(_VIP, {"purchases":[],"next_id":1}, "v")
def _svip(d): _jsave(_VIP, d, "v")
def _ltrf(): return _jload(_TRF, {"transfers":[]}, "t")
def _lsch(): return _jload(_SCH, {"messages":[]}, "s")
def _ssch(d): _jsave(_SCH, d, "s")
def _lcfg():
    with _lk["c"]:
        return db.load_json(_CFG, {"order_registration_active":True})
def _scfg(d):
    with _lk["c"]:
        db.save_json(_CFG, d)

def is_order_registration_active():
    return _lcfg().get("order_registration_active",True)

# ── 📱اطلاعات: خروجی لحظه‌ای تمام «فایل‌های» json ذخیره‌شده (اکنون در PostgreSQL) ──
def _all_json_files():
    """تمام doc_name های موجود در جدول bot_documents (معادل فایل‌های json قدیمی)."""
    try:
        return db.list_docs()
    except Exception:
        return []

def _json_file_has_data(doc_name):
    """رکورد خالی (موجود نباشد یا محتوایش {} / [] / null باشد) نادیده گرفته می‌شود."""
    try:
        return db.doc_has_data(doc_name)
    except Exception:
        return False


# ── state machine ──
_ST = {}; _STL = threading.Lock()
def _gst(a):
    with _STL: return _ST.get(a,{})
def _sst(a,d):
    with _STL: _ST[a]=d
def _cst(a):
    with _STL: _ST.pop(a,None)

# ── scheduled message sender thread ──
def _sch_thread():
    while True:
        try:
            now = datetime.now()
            data = _lsch(); changed = False
            for msg in data["messages"]:
                if msg.get("sent") or msg.get("cancelled"): continue
                try:
                    h,m2 = map(int, msg["send_time"].split(":"))
                    if now.hour==h and now.minute==m2 and now.second<30:
                        users = _lu(); sent_ids=[]; admin_id_str=str(ADMIN_ID)
                        for uid in users:
                            if uid == admin_id_str: continue  # ادمین را skip کن
                            try:
                                mt = msg.get("msg_type","text")
                                content = msg.get("content","")
                                if mt=="text": res=bale_api.send_message(int(uid),content)
                                elif mt=="photo": res=bale_api.send_photo(int(uid),msg.get("file_id",""),caption=content)
                                elif mt=="video": res=bale_api.send_video(int(uid),msg.get("file_id",""),caption=content)
                                elif mt=="audio": res=bale_api.send_audio(int(uid),msg.get("file_id",""),caption=content)
                                elif mt=="document": res=bale_api.send_document(int(uid),msg.get("file_id",""),caption=content)
                                else: res=bale_api.send_message(int(uid),content)
                                if res and res.get("ok"):
                                    sent_ids.append({"uid":uid,"msg_id":res["result"].get("message_id")})
                            except: pass
                        msg["sent"]=True
                        msg["sent_at"]=now.strftime("%Y-%m-%d %H:%M")
                        msg["sent_ids"]=sent_ids
                        changed=True
                        # اطلاع به ادمین
                        try:
                            admin_lang = _get_user_lang(ADMIN_ID)
                            at = _t(ADMIN_ID)
                            bale_api.send_message(ADMIN_ID, at("bc_scheduled_sent_notify"))
                        except: pass
                except: pass
            if changed: _ssch(data)
        except: pass
        _time.sleep(20)

threading.Thread(target=_sch_thread,daemon=True).start()

# ── timed unblock checker ──
def _unblock_thread():
    while True:
        try:
            users=_lu(); changed=False; now=datetime.now()
            for uid,u in users.items():
                if u.get("timed_block_until"):
                    try:
                        until=datetime.fromisoformat(u["timed_block_until"])
                        if now>=until:
                            u["is_blocked"]=False; u.pop("timed_block_until",None); changed=True
                            lang=u.get("lang","fa")
                            at=ADMIN_TEXTS.get(lang) or ADMIN_TEXTS["fa"]
                            bale_api.send_message(int(uid),at.get("timed_block_ended_user",""))
                    except: pass
            if changed: _su(users)
        except: pass
        _time.sleep(60)

threading.Thread(target=_unblock_thread,daemon=True).start()

