def _t(aid):
    lang=_get_user_lang(aid)
    d=ADMIN_TEXTS.get(lang) or ADMIN_TEXTS["fa"]
    fa=ADMIN_TEXTS["fa"]
    return lambda k: d.get(k, fa.get(k,k))

def _get_user_lang(uid):
    try: return _lu().get(str(uid),{}).get("lang","fa")
    except: return "fa"

def _is_any_admin(uid):
    """مالک اصلی + هر مدیر ثانویه‌ی اضافه‌شده."""
    try:
        import handlers as _h
        return _h.is_admin_user(uid)
    except Exception:
        return int(uid) == int(ADMIN_ID)

def _is_owner(uid):
    try:
        import handlers as _h
        return _h.is_owner(uid)
    except Exception:
        return int(uid) == int(ADMIN_ID)

# ══════════════════════════════════════════════════════════════
#  Keyboards
# ══════════════════════════════════════════════════════════════
def _rb(text): return {"text":text}
def _rk(*rows): return {"keyboard":list(rows),"resize_keyboard":True}
def _ik(*rows): return {"inline_keyboard":list(rows)}
def _ibtn(text,cb): return {"text":text,"callback_data":cb}

def _kb_main(aid):
    t=_t(aid)
    rows=[
        [_rb(t("btn_user_mgmt")), _rb(t("btn_order_mgmt"))],
        [_rb(t("btn_broadcast")), _rb(t("btn_payment_mgmt"))],
        [_rb(t("btn_support_mgmt")), _rb(t("btn_channel_mgmt"))],
        [_rb(t("btn_gift_mgmt")), _rb(t("btn_stats"))],
    ]
    if _is_owner(aid):
        rows.append([_rb(t("btn_settings")), _rb(t("btn_admins_mgmt"))])
        rows.append([_rb(t("btn_json_info"))])
    else:
        rows.append([_rb(t("btn_settings"))])
    rows.append([_rb(t("btn_lottery_predict"))])
    rows.append([_rb(t("btn_back"))])
    return _rk(*rows)

