def _kb_wallet_types(lang="fa"):
    labels = _WALLET_TYPE_LABELS.get(lang) or _WALLET_TYPE_LABELS["fa"]
    rows=[]
    items=list(labels.items())
    for i in range(0,len(items),2):
        chunk=items[i:i+2]
        rows.append([{"text":lbl,"callback_data":f"adm:wpt:{key}"} for key,lbl in chunk])
    return {"inline_keyboard":rows}

def _kb_wallet_type_actions(key, lang="fa"):
    al = _WALLET_ACTION_LABELS.get(lang) or _WALLET_ACTION_LABELS["fa"]
    return {"inline_keyboard":[
        [{"text":al["text"],"callback_data":f"adm:wptx:{key}"}],
        [{"text":al["photo"],"callback_data":f"adm:wpti:{key}"}],
    ]}

