_CONTEST_ICON = {"match_prediction": "🥇", "league_prediction": "🏆", "lottery": "🎁", "gift_envelope": "🎁"}

def _contest_label(c, t=None):
    if t is None:
        t = _t(ADMIN_ID)
    icon = _CONTEST_ICON.get(c["type"], "🎯")
    if c["type"] == "match_prediction":
        return f"{icon} {c['team1']} - {c['team2']}"
    if c["type"] == "league_prediction":
        return f"{icon} {c.get('title') or t('cm_league_default')}"
    if c["type"] == "lottery":
        cat_map = {"all": t("cm_lottery_all"), "special": t("cm_lottery_special"), "vip": t("cm_lottery_vip")}
        cat_label = cat_map.get(c.get("category"), "")
        return f"{icon} {t('cm_lottery_label')} {cat_label}"
    if c["type"] == "gift_envelope":
        return f"{icon} {t('btn_gift_envelope')} #{c['id']}"
    return f"{icon} {t('cm_contest_label')} #{c['id']}"

def _send_contest_list(chat_id, admin_id, t, page=0):
    import handlers as _h
    data = _h.load_contests()
    contests = sorted(data["contests"], key=lambda c: (c["status"] != "active", -c["id"]))
    if not contests:
        bale_api.send_message(chat_id, t("cm_empty"), reply_markup=_kb_lottery_predict(admin_id))
        return
    per_page = 10
    total_pages = max(1, (len(contests) + per_page - 1) // per_page)
    page = max(0, min(page, total_pages - 1))
    chunk = contests[page*per_page:(page+1)*per_page]
    rows = [[{"text": _contest_label(c, t), "callback_data": f"adm:cm_sel:{c['id']}"}] for c in chunk]
    nav = []
    if page > 0:
        nav.append({"text": t("btn_prev_page"), "callback_data": f"adm:cm_page:{page-1}"})
    if page < total_pages - 1:
        nav.append({"text": t("btn_next_page"), "callback_data": f"adm:cm_page:{page+1}"})
    if nav:
        rows.append(nav)
    bale_api.send_message(chat_id, t("cm_select_prompt"), reply_markup={"inline_keyboard": rows})

