def build_reply_main_menu_admin(lang="fa"):
    at=ADMIN_TEXTS.get(lang) or ADMIN_TEXTS["fa"]
    admin_btn=at.get("btn_admin_panel","⚙️ پنل ادمین")
    try:
        import handlers as _h
        base_kb = _h.build_reply_main_menu(lang)
        rows = [[{"text": admin_btn}]] + base_kb["keyboard"]
        return {"keyboard": rows, "resize_keyboard": True}
    except Exception:
        # fallback ایمن در صورت بروز خطای غیرمنتظره در import
        return {"keyboard": [[{"text": admin_btn}]], "resize_keyboard": True}

# ══════════════════════════════════════════════════════════════
#  توابع کمکی
# ══════════════════════════════════════════════════════════════
def _fmt_date(raw):
    if not raw: return datetime.now().strftime("%Y-%m-%d\n🕐 %H:%M")
    s=str(raw).replace("T"," ")
    parts=s[:16].split(" ")
    return f"{parts[0]}\n🕐 {parts[1]}" if len(parts)==2 else s[:16]

def _tag(uid):
    if not uid: return "—"
    u=_lu().get(str(uid),{})
    un=u.get("username","")
    if un: return f"@{un}"
    nm=u.get("first_name","")
    return f"{nm} (#{uid})" if nm else f"#{uid}"

def _find_user_by_alpha(text, users):
    text=text.strip().lstrip("@")
    for uid,u in users.items():
        if (u.get("username") or "").lower()==text.lower(): return uid,u
    return None,None

def _find_user_by_numeric(text, users):
    text=text.strip()
    if text in users: return text,users[text]
    return None,None

def _norm_phone(raw):
    """شماره رو به فرمت یکسان 98XXXXXXXXXX تبدیل می‌کنه (بدون + و بدون صفر اول)."""
    if not raw: return ""
    digits="".join(ch for ch in str(raw) if ch.isdigit())
    if digits.startswith("0098"): digits=digits[2:]
    if digits.startswith("98") and len(digits)==12: return digits
    if digits.startswith("0") and len(digits)==11: return "98"+digits[1:]
    if digits.startswith("9") and len(digits)==10: return "98"+digits
    return digits

def _find_user_by_phone(text, users):
    text=_norm_phone(text.strip())
    for uid,u in users.items():
        if _norm_phone(u.get("phone_number") or "")==text: return uid,u
    return None,None

def _find_user_by_input(text, users, mode):
    if mode=="id": return _find_user_by_alpha(text,users)
    if mode=="num": return _find_user_by_numeric(text,users)
    if mode=="phone": return _find_user_by_phone(text,users)
    return None,None

def _send_long(chat_id, text, chunk=3500):
    while len(text)>chunk:
        bale_api.send_message(chat_id,text[:chunk]); text=text[chunk:]
    if text.strip(): bale_api.send_message(chat_id,text)

def _not_found_msg(mode, t):
    if mode=="id": return t("user_not_found_id")
    if mode=="num": return t("user_not_found_username")
    return t("user_not_found_phone")

