def _fmt_user(uid,u,lang="fa"):
    L=_FMT_LABELS.get(lang) or _FMT_LABELS["fa"]
    un=u.get("username",""); tag=f"@{un}" if un else L["na"]
    vip=L["vip"] if u.get("is_vip") or u.get("vip_until") else L["normal"]
    blk=L["yes"] if u.get("is_blocked") else L["no"]
    orders=_lo(); cnt=sum(1 for o in orders.get("orders",[]) if str(o.get("user_id",""))==str(uid))
    try:
        import handlers as _h
        join_date=_h._fmt_jalali_datetime(_h.datetime.fromisoformat(u.get("joined_at")))
    except Exception:
        join_date=L["na"]
    return (f"{L['user_title']}\n\n{L['id']}: `{uid}`\n{L['name']}: {u.get('first_name',L['na'])}\n"
            f"{L['username']}: {tag}\n{L['phone']}: {u.get('phone_number',L['na'])}\n"
            f"{L['coins']}: {round(u.get('coins',0),2)}\n{L['orders']}: {cnt}\n"
            f"{L['status']}: {vip}\n{L['inviter']}: {int(u.get('referrals',0))}\n{L['blocked']}: {blk}\n{L['lang']}: {u.get('lang','fa')}\n"
            f"{L['joined']}: {join_date}")

def _status_label(s,lang="fa"):
    L=_FMT_LABELS.get(lang) or _FMT_LABELS["fa"]
    return {"active":L["st_active"],"completed":L["st_completed"],
            "cancelled":L["st_cancelled"],"pending":L["st_pending"]}.get(s,s)

def _type_label(tp,lang="fa"):
    L=_FMT_LABELS.get(lang) or _FMT_LABELS["fa"]
    return {"member":L["tp_member"]}.get(tp,tp)

def _tracking(order):
    tp=order.get("_type","member")
    if tp=="member": return str(order.get("order_id",""))
    return str(order.get("order_id",order.get("id","")))

def _fmt_order(order,lang="fa"):
    L=_FMT_LABELS.get(lang) or _FMT_LABELS["fa"]
    tp=order.get("_type","member"); tr=_tracking(order)
    st=_status_label(order.get("status","active"),lang); tl=_type_label(tp,lang)
    ch=order.get("channel_id") or order.get("post_link") or order.get("link",L["na2"])
    ow=order.get("user_id",L["na2"]); ow_tag=_tag(ow)
    cr_fmt=_fmt_date(order.get("created_at",""))
    if tp=="member":
        tot=order.get("member_count",0); done=order.get("members_joined",0)
    else:
        tot=0; done=0
    return (f"{L['order_title']}\n━━━━━━━━━━━━━━━━━\n"
            f"{L['code']}: `#{tr}`\n{L['type']}: {tl}\n{L['order_status']}: {st}\n"
            f"━━━━━━━━━━━━━━━━━\n{L['link']}:\n`{ch}`\n"
            f"━━━━━━━━━━━━━━━━━\n{L['user']}: {ow_tag}\n"
            f"{L['total']}: {tot}  |  {L['done']}: {done}  |  {L['remaining']}: {max(0,tot-done)}\n"
            f"━━━━━━━━━━━━━━━━━\n{L['reg_date']}: {cr_fmt}")

def _find_order(code):
    code=code.strip().lstrip("#").upper()
    for o in _lo().get("orders",[]):
        if str(o.get("order_id",""))==code: o["_type"]="member"; return o
    return None

def _cancel_and_refund(order, admin_id):
    tp=order.get("_type","member"); tr=_tracking(order); ow=order.get("user_id")
    refund=0.0
    def _del_ch_msg(d, key_mid="channel_message_id"):
        # نکته: پیام سفارش همیشه در کانال اصلی آرکا منتشر می‌شود، نه در کانال خود کاربر؛
        # پس باگ قبلی (استفاده از channel_id کاربر به عنوان مقصد) اصلاح شد.
        mid=d.get(key_mid) or d.get("message_id")
        if mid:
            try: bale_api.delete_message(CHANNEL_USERNAME,mid)
            except: pass
    if tp=="member":
        done=order.get("members_joined",0); total=order.get("member_count",0)
        refund=max(0,total-done)*2.0
        orders=_lo()
        for o in orders["orders"]:
            if str(o.get("order_id",""))==str(order.get("order_id","")):
                o["status"]="cancelled"; _del_ch_msg(o); break
        _so(orders)
    refund=round(refund,2)
    if refund>0 and ow:
        users=_lu(); uid=str(ow); u=users.get(uid,{})
        u["coins"]=round(u.get("coins",0)+refund,2); users[uid]=u; _su(users)
    return tr

def _change_order_status(order, new_status):
    tp=order.get("_type","member")
    def _del(d, key_mid="channel_message_id"):
        # پیام سفارش در کانال اصلی آرکا منتشر می‌شود، نه در کانال خود کاربر
        mid=d.get(key_mid) or d.get("message_id")
        if mid:
            try: bale_api.delete_message(CHANNEL_USERNAME,mid)
            except: pass
    if tp=="member":
        orders=_lo()
        for o in orders["orders"]:
            if str(o.get("order_id",""))==str(order.get("order_id","")):
                o["status"]=new_status
                if new_status in ("completed","cancelled"): _del(o)
                break
        _so(orders)

def _is_vip_active(u):
    if not u.get("vip_until"): return False
    try: return datetime.now()<datetime.fromisoformat(u["vip_until"])
    except: return False

def _send_to_group(chat_id, aid, message, group="all"):
    """ارسال broadcast به گروه مشخص"""
    users=_lu(); count=0
    now=datetime.now()
    for uid,u in users.items():
        try:
            skip=False
            if group=="vip" and not _is_vip_active(u): skip=True
            if group=="normal" and _is_vip_active(u): skip=True
            if group=="inactive":
                last=u.get("last_seen")
                if last:
                    try:
                        diff=(now-datetime.fromisoformat(last)).days
                        if diff<7: skip=True
                    except: skip=True
                else: skip=True
            if not skip:
                mt=message.get("msg_type","text")
                if mt=="text": bale_api.send_message(int(uid),message.get("content",""))
                elif mt=="photo": bale_api.send_photo(int(uid),message.get("file_id",""),caption=message.get("content",""))
                elif mt=="video": bale_api.send_video(int(uid),message.get("file_id",""),caption=message.get("content",""))
                elif mt=="audio": bale_api.send_audio(int(uid),message.get("file_id",""),caption=message.get("content",""))
                elif mt=="document": bale_api.send_document(int(uid),message.get("file_id",""),caption=message.get("content",""))
                else: bale_api.send_message(int(uid),message.get("content",""))
                count+=1
        except: pass
    return count

def _give_vip(uid_str, days):
    users=_lu(); u=users.get(uid_str,{})
    now=datetime.now()
    try: current=datetime.fromisoformat(u.get("vip_until",""))
    except: current=now
    new_until=max(current,now)+timedelta(days=days)
    u["vip_until"]=new_until.isoformat(); u["is_vip"]=True
    users[uid_str]=u; _su(users)

# ══════════════════════════════════════════════════════════════
#  handle_admin_text_input — اصلی
# ══════════════════════════════════════════════════════════════
def handle_admin_non_text(chat_id, admin_id, message) -> bool:
    """وقتی ادمین به‌جای متن، عکس/فایل/صوت/ویدیو و... می‌فرسته در حالت‌هایی که فقط متن مجاز است."""
    if not _is_any_admin(admin_id): return False
    st = _gst(admin_id); action = st.get("action","")
    t = _t(admin_id)
    # ─── Broadcast: دریافت عکس/ویدئو/فایل/صوت ───
    if action == "wait_bc_msg":
        bc_type = st.get("bc_type", "all")

        if message.get("photo"):
            msg_data = {
                "content": message.get("caption", ""),
                "msg_type": "photo",
                "file_id": message["photo"][-1]["file_id"],
            }

        elif message.get("video"):
            msg_data = {
                "content": message.get("caption", ""),
                "msg_type": "video",
                "file_id": message["video"]["file_id"],
            }

        elif message.get("audio"):
            msg_data = {
                "content": message.get("caption", ""),
                "msg_type": "audio",
                "file_id": message["audio"]["file_id"],
            }

        elif message.get("document"):
            msg_data = {
                "content": message.get("caption", ""),
                "msg_type": "document",
                "file_id": message["document"]["file_id"],
            }

        else:
            return False

        if bc_type == "scheduled":
            _sst(
                admin_id,
                {
                    **st,
                    "action": "wait_bc_scheduled_time",
                    "pending_msg": msg_data,
                },
            )

            bale_api.send_message(
                chat_id,
                t("bc_scheduled_time"),
                reply_markup=_kb_back(admin_id),
            )

        else:
            _sst(
                admin_id,
                {
                    **st,
                    "action": "wait_bc_msg_confirm",
                    "pending_msg": msg_data,
                },
            )

            preview_text = msg_data.get("content", "")

            bale_api.send_message(
                chat_id,
                t(
                    {
                        "all": "bc_all_preview",
                        "vip": "bc_vip_preview",
                        "normal": "bc_normal_preview",
                        "inactive": "bc_inactive_preview",
                    }.get(bc_type, "bc_all_preview")
                ).format(msg=preview_text or "📷 تصویر"),
                reply_markup=_kb_confirm_abort(admin_id),
            )

        return True
    if action == "wait_gift_code_text":
        bale_api.send_message(chat_id, t("gift_code_text_only"))
        return True
        # ─── دریافت عکس برای پیام همگانی ───
    if action == "wait_bc_msg":

        bc_type = st.get("bc_type", "all")

        if message.get("photo"):
            msg_data = {
                "content": message.get("caption", ""),
                "msg_type": "photo",
                "file_id": message["photo"][-1]["file_id"],
            }

        elif message.get("video"):
            msg_data = {
                "content": message.get("caption", ""),
                "msg_type": "video",
                "file_id": message["video"]["file_id"],
            }

        elif message.get("audio"):
            msg_data = {
                "content": message.get("caption", ""),
                "msg_type": "audio",
                "file_id": message["audio"]["file_id"],
            }

        elif message.get("document"):
            msg_data = {
                "content": message.get("caption", ""),
                "msg_type": "document",
                "file_id": message["document"]["file_id"],
            }

        else:
            return False

        # ذخیره پیام برای تأیید
        _sst(
            admin_id,
            {
                **st,
                "action": "wait_bc_msg_confirm",
                "pending_msg": msg_data,
            },
        )

        # نمایش خود عکس/رسانه به عنوان Preview
        if msg_data["msg_type"] == "photo":
            bale_api.send_photo(
                chat_id,
                msg_data["file_id"],
                caption=msg_data["content"],
            )

        elif msg_data["msg_type"] == "video":
            bale_api.send_video(
                chat_id,
                msg_data["file_id"],
                caption=msg_data["content"],
            )

        elif msg_data["msg_type"] == "audio":
            bale_api.send_audio(
                chat_id,
                msg_data["file_id"],
                caption=msg_data["content"],
            )

        elif msg_data["msg_type"] == "document":
            bale_api.send_document(
                chat_id,
                msg_data["file_id"],
                caption=msg_data["content"],
            )

        # پیام تأیید
        bale_api.send_message(
            chat_id,
            "آیا این پیام را برای ارسال تأیید می‌کنید؟",
            reply_markup=_kb_confirm_abort(admin_id),
        )

        return True
    if action == "pw_wait_poster":
        photo = message.get("photo")
        if not photo:
            bale_api.send_message(chat_id, t("pw_photo_only_error"))
            return True
        draft = st.get("draft", {})
        draft["poster_file_id"] = photo[-1]["file_id"]
        _sst(admin_id, {"action": "pw_wait_draw", "draft": draft})
        kb = {"inline_keyboard": [[
            {"text": t("btn_yes"), "callback_data": "adm:pw_draw:yes"},
            {"text": t("btn_no"), "callback_data": "adm:pw_draw:no"},
        ]]}
        bale_api.send_message(chat_id, t("pw_draw_prompt"), reply_markup=kb)
        return True
    if action == "lw_wait_poster":
        photo = message.get("photo")
        if not photo:
            bale_api.send_message(chat_id, t("pw_photo_only_error"))
            return True
        draft = st.get("draft", {})
        draft["poster_file_id"] = photo[-1]["file_id"]
        _sst(admin_id, {"action": "lw_wait_count", "draft": draft})
        bale_api.send_message(chat_id, t("lw_teams_count_prompt"))
        return True
    return False


def handle_admin_ucbc_message(chat_id, admin_id, message) -> bool:
    """
    پیام یا فوروارد ادمین برای بخش «ارسال به کانال کاربران» را می‌گیرد،
    نوع محتوا/فوروارد بودن آن را ذخیره می‌کند و پیش‌نمایش+تأیید نشان می‌دهد.
    این تابع هم برای پیام متنی و هم غیرمتنی فراخوانی می‌شود.
    """
    if not _is_any_admin(admin_id):
        return False
    st = _gst(admin_id)
    if st.get("action") != "wait_ucbc_msg":
        return False
    t = _t(admin_id)
    is_forward = bool(
        message.get("forward_from") or message.get("forward_from_chat")
        or message.get("forward_date") or message.get("forward_sender_name")
    )
    draft = {
        "is_forward": is_forward,
        "from_chat_id": chat_id,
        "message_id": message.get("message_id"),
    }
    if not is_forward:
        if message.get("photo"):
            draft["msg_type"] = "photo"; draft["file_id"] = message["photo"][-1]["file_id"]; draft["content"] = message.get("caption", "")
        elif message.get("video"):
            draft["msg_type"] = "video"; draft["file_id"] = message["video"]["file_id"]; draft["content"] = message.get("caption", "")
        elif message.get("audio"):
            draft["msg_type"] = "audio"; draft["file_id"] = message["audio"]["file_id"]; draft["content"] = message.get("caption", "")
        elif message.get("document"):
            draft["msg_type"] = "document"; draft["file_id"] = message["document"]["file_id"]; draft["content"] = message.get("caption", "")
        else:
            draft["msg_type"] = "text"; draft["content"] = message.get("text", "")
    _sst(admin_id, {"action": "wait_ucbc_confirm", "draft": draft, "prev": "broadcast"})
    kb = {"inline_keyboard": [[
        {"text": t("btn_confirm_yes"), "callback_data": "adm:ucbc_confirm:yes"},
        {"text": t("btn_confirm_no"), "callback_data": "adm:ucbc_confirm:no"},
    ]]}
    bale_api.send_message(chat_id, t("bc_channels_preview"), reply_markup=kb)
    return True


